const root = "/w/node_modules/agents";
(async () => {
  const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
  const mod = await import(pathToFileURL(path.join(root, "dist/sessions/index.js")).href);
  const db = new DatabaseSync(":memory:");
  const kv = new Map();
  const storage = {
    sql: {
      exec(query, ...params) {
        const stmt = db.prepare(query);
        if (stmt.columns().length > 0) {
          const out = stmt.all(...params).map((r) => ({ ...r }));
          out.rowsWritten = 0;
          return out;
        }
        const info = stmt.run(...params);
        const out = [];
        out.rowsWritten = Number(info.changes);
        return out;
      }
    },
    transactionSync(fn) {
      db.exec("SAVEPOINT t");
      try {
        const r = fn();
        db.exec("RELEASE t");
        return r;
      } catch (e) {
        db.exec("ROLLBACK TO t");
        db.exec("RELEASE t");
        throw e;
      }
    },
    async get(k) { return kv.get(k); },
    async put(k, v) { kv.set(k, v); }
  };
  let started;
  const services = { storage, events: { emit() {} }, ready: () => started };
  class TestSessions extends mod.Sessions {
    get lifecycle() { return services; }
  }
  const sessions = new TestSessions();
  started = sessions.onStart();
  await started;
  const s = sessions.session("s1");
  const msg = (id, role, text) => ({ id, role, parts: [{ type: "text", text }] });
  await s.appendMessage(msg("m1", "user", "hello"));
  await s.appendMessage(msg("m2", "assistant", "hi there"));
  await s.appendMessage(msg("m3", "user", "more"));
  await s.addCompaction("summary of m1 and m2", "m1", "m2");
  const before = await s.getHistory();
  const overlay = before.find((m) => mod.isCompactionMessage(m));
  if (!overlay) {
    console.error("ERROR: no compaction overlay in history: " + JSON.stringify(before.map((m) => m.id)));
    process.exit(2);
  }
  // A client posts its transcript back, echoing the overlay.
  await s.appendMessage(overlay);
  await s.appendMessage(msg("m4", "user", "next turn"));
  const ids = (await s.getHistory()).map((m) => m.id);
  const copies = ids.filter((id) => id === overlay.id).length;
  if (copies === 1 && ids[ids.length - 1] === "m4") {
    console.log("OK: agents " + pkg.version + " did not store echoed overlay; history " + JSON.stringify(ids));
    process.exit(0);
  }
  if (copies > 1) {
    console.error("FAIL: echoed compaction overlay was stored and repeats in getHistory");
    process.exit(1);
  }
  console.error("ERROR: unexpected history " + JSON.stringify(ids));
  process.exit(2);
})().catch((e) => {
  console.error("ERROR: " + ((e && e.stack) || e));
  process.exit(2);
});

